pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a token that fails on transferFrom for the second recipient
        address token = address(new FailingToken());
        address from = address(0x123);
        address[] memory tos = new address[](2);
        tos[0] = address(0x456);
        tos[1] = address(0x789);
        // Fund the token with some allowance
        vm.prank(from);
        FailingToken(token).approve(address(c), 100);
        // The reference version reverts because second transferFrom fails
        // The buggy version ignores the failure and returns true
        // We catch the revert with a try/catch
        bool ok;
        try c.transfer(from, token, tos, 50) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference version: reverts => ok is false
        // Buggy version: succeeds => ok is true
        // To detect divergence: the assertion checks that the call reverted
        assertTrue(!ok);
    }
}

contract FailingToken {
    mapping(address => mapping(address => uint)) public allowance;
    function approve(address spender, uint amount) external { allowance[msg.sender][spender] = amount; }
    function transferFrom(address, address, uint) external pure returns (bool) {
        // Reverts on any call
        revert("transferFrom always fails");
    }
}

