pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple token that tracks transferFrom calls
        Token token = new Token();
        // Approve the token for transferFrom (address(this) is from)
        vm.prank(address(this));
        token.approve(address(c), 100);
        // Prepare a singleton array
        address[] memory tos = new address[](1);
        tos[0] = address(0x123);
        // Call transfer on C; it will attempt transferFrom on token
        bool ok;
        try c.transfer(address(this), address(token), tos, 100) {
            ok = true;
        } catch {
            ok = false;
        }
        // Check that the token's balanceOf for the recipient increased
        uint256 balance = token.balanceOf(address(0x123));
        assertTrue(ok && balance == 100);
    }
}

contract Token {
    mapping(address => mapping(address => uint256)) public allowance;
    mapping(address => uint256) public balanceOf;
    function approve(address spender, uint256 amount) public returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }
    function transferFrom(address from, address to, uint256 amount) public returns (bool) {
        require(allowance[from][msg.sender] >= amount);
        allowance[from][msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

